CREATE COLUMN TABLE "TEST_AP"."CPV23" ("DocEntry" INTEGER CS_INT NOT NULL , "LineNum" INTEGER CS_INT NOT NULL , "AssetCode" NVARCHAR(50), "Status" NVARCHAR(1) DEFAULT 'O', "Remarks" NVARCHAR(100), "Amount" DECIMAL(21,6) CS_FIXED, "AmountSC" DECIMAL(21,6) CS_FIXED, "SerialNo" NVARCHAR(30), "VisOrder" INTEGER CS_INT NOT NULL , "LogInstanc" INTEGER CS_INT DEFAULT 0, "ObjectType" NVARCHAR(20) DEFAULT '19', PRIMARY KEY ("DocEntry", "LineNum", "VisOrder")) UNLOAD PRIORITY 5  AUTO MERGE ;
ALTER TABLE "TEST_AP"."CPV23" WITH PARAMETERS ('CONCAT_ATTRIBUTE'=('$DocEntry$LineNum$AssetCode$','DocEntry','LineNum','AssetCode'));
CREATE INDEX "CPV23_ASSETS" ON "TEST_AP"."CPV23" ( "DocEntry" ASC, "LineNum" ASC, "AssetCode" ASC )